if (points.empty()) {
    return BoundingBox2();
}

std::vector<Point2d> hull;
std::vector<Point2d> pts = points;
std::sort(pts.begin(), pts.end(), [](const Point2d& a, const Point2d& b) {
    return a.x < b.x || (a.x == b.x && a.y < b.y);
});

std::vector<Point2d> sorted_points;
{
    size_t n = pts.size();
    if (n < 2) {
        if (n == 1) {
            return BoundingBox2{pts[0], pts[0]};
        } else {
            return BoundingBox2();
        }
    }
    std::vector<int> indices(n);
    for (size_t i = 0; i < n; i++) indices[i] = i;
    std::sort(indices.begin(), indices.end(), [&pts](int a, int b) {
        return pts[a].y < pts[b].y || (pts[a].y == pts[b].y && pts[a].x < pts[b].x);
    });
    for (int i : indices) {
        sorted_points.push_back(pts[i]);
    }
}
pts = sorted_points;

std::vector<Point2d> upper(2 * n), lower(2 * n);
int k = 0;
for (size_t i = 0; i < n; i++) {
    while (k >= 2 && cross(upper[k-2], upper[k-1], pts[i]) <= 0) k--;
    upper[k++] = pts[i];
}
int k_upper = k;
k = 0;
for (int i = n - 1; i >= 0; i--) {
    while (k >= 2 && cross(lower[k-2], lower[k-1], pts[i]) <= 0) k--;
    lower[k++] = pts[i];
}
int k_lower = k;

hull.insert(hull.end(), upper.begin(), upper.begin() + k_upper);
hull.insert(hull.end(), lower.begin(), lower.begin() + k_lower);

if (hull.size() < 2) {
    return BoundingBox2(hull[0], hull[0]);
}

double min_area = std::numeric_limits<double>::max();
Point2d min_corner, max_corner;

for (size_t i = 0; i < hull.size(); i++) {
    Point2d edge = hull[(i + 1) % hull.size()] - hull[i];
    double edge_length = std::sqrt(edge.x * edge.x + edge.y * edge.y);
    if (edge_length == 0) continue;

    edge.x /= edge_length;
    edge.y /= edge_length;

    Point2d normal(-edge.y, edge.x);

    double min_proj = std::numeric_limits<double>::max();
    double max_proj = -std::numeric_limits<double>::max();
    double min_normal = std::numeric_limits<double>::max();
    double max_normal = -std::numeric_limits<double>::max();

    for (const auto& p : points) {
        Point2d vec = p - hull[i];
        double proj = vec.x * edge.x + vec.y * edge.y;
        double norm = vec.x * normal.x + vec.y * normal.y;

        min_proj = std::min(min_proj, proj);
        max_proj = std::max(max_proj, proj);
        min_normal = std::min(min_normal, norm);
        max_normal = std::max(max_normal, norm);
    }

    double area = (max_proj - min_proj) * (max_normal - min_normal);
    if (area < min_area) {
        min_area = area;
        Point2d projected_min(min_proj * edge.x + min_normal * normal.x + hull[i].x, 
                          min_proj * edge.y + min_normal * normal.y + hull[i].y);
        Point2d projected_max(max_proj * edge.x + max_normal * normal.x + hull[i].x,
                              max_proj * edge.y + max_normal * normal.y + hull[i].y);
        min_corner = projected_min;
        max_corner = projected_max;
    }
}

return BoundingBox2(min_corner, max_corner);
// END_CODE

